import {
  MeshStandardNodeMaterial,
  color,
  uv,
  mix,
  smoothstep,
  uniform,
  vec3
} from 'three/webgpu';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Create local timelines tracker for cleanup
  const activeTimelines = [];

  // --- STAGE BACKDROP (W-PCP §9 - No black voids) ---
  const backdropGeo = new THREE.PlaneGeometry(8, 7);
  const backdropMat = new MeshStandardNodeMaterial({
    roughness: 0.8,
    metalness: 0.1
  });

  // Custom TSL gradient for backdrop matching the brand: ink (#16161d) to near-black (#0b0b10)
  const vUv = uv();
  const gradColor = mix(
    color('#0b0b10'),
    color('#16161d'),
    vUv.y
  );
  backdropMat.colorNode = gradColor;

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -1.2;
  group.add(backdrop);

  // --- LOCAL LIGHTING (W-PCP §9 Product Shot) ---
  const localKeyLight = new THREE.DirectionalLight('#e8ecf2', 1.2);
  localKeyLight.position.set(2, 4, 3);
  group.add(localKeyLight);

  const localAccentLight = new THREE.DirectionalLight('#ff2a38', 0.8);
  localAccentLight.position.set(-3, -2, 1);
  group.add(localAccentLight);

  // --- CONTACT SHADOW ---
  const shadowGeo = new THREE.PlaneGeometry(2.8, 0.8);
  const shadowMat = new MeshStandardNodeMaterial({
    color: '#000000',
    roughness: 1.0,
    transparent: true,
    opacity: 0.35
  });
  const contactShadow = new THREE.Mesh(shadowGeo, shadowMat);
  contactShadow.position.set(0, -0.4, -0.05);
  group.add(contactShadow);

  // --- THE ENGINEERED GRADIENT BUTTON ---
  // Button specs: 2.6w x 0.68h, custom bevelized look.
  // We represent the 3D button with a rounded box/extruded panel to satisfy "interactive elements are extruded 3D objects with bevel"
  const buttonWidth = 2.6;
  const buttonHeight = 0.68;
  const buttonDepth = 0.04;
  const radius = 0.08;

  // Build a custom rounded extruded panel shape
  const shape = new THREE.Shape();
  const x = -buttonWidth / 2;
  const y = -buttonHeight / 2;
  shape.moveTo(x + radius, y);
  shape.lineTo(x + buttonWidth - radius, y);
  shape.quadraticCurveTo(x + buttonWidth, y, x + buttonWidth, y + radius);
  shape.lineTo(x + buttonWidth, y + buttonHeight - radius);
  shape.quadraticCurveTo(x + buttonWidth, y + buttonHeight, x + buttonWidth - radius, y + buttonHeight);
  shape.lineTo(x + radius, y + buttonHeight);
  shape.quadraticCurveTo(x, y + buttonHeight, x, y + buttonHeight - radius);
  shape.lineTo(x, y + radius);
  shape.quadraticCurveTo(x, y, x + radius, y);

  const extrudeSettings = {
    steps: 1,
    depth: buttonDepth,
    bevelEnabled: true,
    bevelThickness: 0.015,
    bevelSize: 0.01,
    bevelSegments: 3
  };

  const buttonGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  buttonGeo.center();

  // Engineered Gradient TSL
  const buttonMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    transparent: false
  });

  // Hotspot TSL for machined bevel look & horizontal hard split seam at y=0.5
  // We create uniform values to animate or drive transitions
  const emissiveLevel = uniform(1.6);
  const emissiveColor = color('#ff2a38');

  // Multi-stop gradient logic: #ff4450 -> #ff2a38 -> #c1121f
  // With one hard 0.01-unit seam line at 50% face height
  const tslUv = uv();
  const gradientStops = () => {
    const yVal = tslUv.y;
    // Hard boundary seam line
    const seam = smoothstep(0.495, 0.505, yVal);
    const gradLow = mix(color('#ff4450'), color('#ff2a38'), yVal.mul(1.81));
    const gradHigh = mix(color('#ff2a38'), color('#c1121f'), yVal.sub(0.55).mul(2.22));
    const rawGrad = mix(gradLow, gradHigh, seam);

    // Perimeter accent/emissive mock within material color
    const edge = smoothstep(0.0, 0.03, tslUv.x)
      .mul(smoothstep(1.0, 0.97, tslUv.x))
      .mul(smoothstep(0.0, 0.12, tslUv.y))
      .mul(smoothstep(1.0, 0.88, tslUv.y));
    const edgeFactor = vec3(1.0).sub(edge);

    return mix(rawGrad, emissiveColor.mul(emissiveLevel), edgeFactor.mul(0.1));
  };

  buttonMat.colorNode = gradientStops();
  buttonMat.emissiveNode = emissiveColor.mul(emissiveLevel.mul(0.06));

  const buttonMesh = new THREE.Mesh(buttonGeo, buttonMat);
  group.add(buttonMesh);

  // --- TYPOGRAPHY / LABELS ---
  // Font atlas creations
  const textGroup = new THREE.Group();
  textGroup.position.z = buttonDepth + 0.025; // Sit proud of extruded surface

  const rawCtaText = "BEGIN COMMISSION";
  const rawCaptionText = "NO DEPOSIT REQUIRED";

  // Display mono CTA label
  const ctaLabel = ctx.fontAtlas.createText(rawCtaText, {
    fontSize: 20 * 0.007, // scaled to match brand spec scale safely
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.6
  });
  ctaLabel.position.set(0, 0.02, 0.005);
  textGroup.add(ctaLabel);

  // Captions placed below the visual button
  const captionLabel = ctx.fontAtlas.createText(rawCaptionText, {
    fontSize: 9 * 0.008,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2.2
  });
  captionLabel.position.set(0, -0.6, 0.001);
  group.add(captionLabel);

  buttonMesh.add(textGroup);

  // --- ANIMATIONS & INTERACTIONS ---

  // Mount Settle (overshoot 1.04 -> 1.0 over 900ms)
  buttonMesh.scale.set(0.1, 0.1, 0.1);
  const mountTl = gsap.timeline();
  activeTimelines.push(mountTl);
  mountTl.to(buttonMesh.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.5,
    ease: "power2.out"
  }).to(buttonMesh.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.4,
    ease: "power4.out"
  });

  // Interactive hooks on the Group node
  const onHoverStart = () => {
    gsap.to(buttonMesh.position, {
      z: 0.06,
      duration: 0.18,
      ease: "power1.out"
    });
    gsap.to(emissiveLevel, {
      value: 2.2,
      duration: 0.18,
      ease: "power1.out"
    });
    // Emit micro-interaction sound trigger hint via app controller
    ctx.emit('button:hover', { active: true });
  };

  const onHoverEnd = () => {
    gsap.to(buttonMesh.position, {
      z: 0.0,
      duration: 0.25,
      ease: "power2.out"
    });
    gsap.to(emissiveLevel, {
      value: 1.6,
      duration: 0.25,
      ease: "power2.out"
    });
  };

  const onPressDown = () => {
    const pressTl = gsap.timeline();
    activeTimelines.push(pressTl);
    pressTl.to(buttonMesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: "back.out(2)"
    });
    gsap.to(contactShadow.scale, {
      x: 0.85,
      y: 0.85,
      duration: 0.12
    });
    gsap.to(contactShadow.material, {
      opacity: 0.6,
      duration: 0.12
    });
  };

  const onPressUp = () => {
    gsap.to(buttonMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2,
      ease: "power2.out"
    });
    gsap.to(contactShadow.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.2
    });
    gsap.to(contactShadow.material, {
      opacity: 0.35,
      duration: 0.2
    });
    ctx.emit('navigate', { to: 'hub-pricing' });
  };

  // Wire up handlers for pointer raycaster
  group.userData.handlers = {
    pointerover: onHoverStart,
    pointerout: onHoverEnd,
    pointerdown: onPressDown,
    pointerup: onPressUp
  };

  // Custom Cleanup protocol
  group.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    buttonGeo.dispose();
    buttonMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return group;
}
